            maximums.append(_round_output(max(day_values)))
            uncertainties.append(
                _round_output(
                    math.sqrt(sum(u * u for u in day_uncertainties)) / count
                )
            )
        out_data[name] = {
            "count": counts,
            "mean": means,
            "min": minimums,
            "max": maximums,
            "uncertainty": uncertainties,
        }

    return {
        "schema": _SCHEMA,
        "element": element,
        "times": list(times),
        "regions": [name for name, _ in parsed_regions],
        "data": out_data,
    }
